/*
  Servo Sweep
  Moves a hobby servo slowly from 0 to 180 degrees and back again.

  The servo signal wire goes to pin 9, red to 5V, brown/black to GND.
*/

#include <Servo.h>

Servo myservo;  // create a servo object to control a servo

int pos = 0;    // variable to store the servo position

void setup() {
  myservo.attach(9);  // attaches the servo on pin 9 to the servo object
}

void loop() {
  // go from 0 to 180 degrees, one degree at a time
  for (pos = 0; pos <= 180; pos += 1) {
    myservo.write(pos);   // tell the servo to go to position 'pos'
    delay(15);            // wait 15ms for the servo to reach the position
  }

  // now go back from 180 to 0 degrees
  for (pos = 180; pos >= 0; pos -= 1) {
    myservo.write(pos);
    delay(15);
  }
}

