/*
  Potentiometer controlled servo

  Turn the knob and the servo follows it.
  Potentiometer middle pin -> A0, outer pins -> 5V and GND.
*/

#include <Servo.h>

Servo myServo;

const int potPin = A0;     // analog pin the potentiometer is connected to
const int servoPin = 9;    // servo signal pin

int potValue = 0;          // raw value read from the potentiometer (0-1023)
int angle = 0;             // servo angle in degrees (0-180)

void setup() {
  Serial.begin(9600);
  myServo.attach(servoPin);
}

void loop() {
  potValue = analogRead(potPin);

  // the analog reading is 0-1023, the servo wants 0-180
  angle = map(potValue, 0, 1023, 0, 180);

  myServo.write(angle);

  Serial.print("pot = ");
  Serial.print(potValue);
  Serial.print("  angle = ");
  Serial.println(angle);

  delay(20);  // give the servo a little time to move
}

