/*
  Serial controlled servo

  Open the Serial Monitor, type a number between 0 and 180,
  press Enter, and the servo moves there.
*/

#include <Servo.h>

#define SERVO_PIN 9

Servo gateServo;

int currentAngle = 90;

void setup() {
  Serial.begin(9600);

  gateServo.attach(SERVO_PIN);
  gateServo.write(currentAngle);   // start in the middle

  Serial.println("Servo ready.");
  Serial.println("Type an angle between 0 and 180 and press Enter.");
}

void loop() {
  if (Serial.available() > 0) {
    int angle = Serial.parseInt();

    if (angle >= 0 && angle <= 180) {
      currentAngle = angle;
      gateServo.write(currentAngle);

      Serial.print("Moving servo to ");
      Serial.print(currentAngle);
      Serial.println(" degrees");
    } else {
      Serial.println("Out of range! Please enter 0 to 180.");
    }
  }
}

