/*
  DHT11 basic reading

  Prints temperature and humidity to the Serial Monitor every 2 seconds.
  Needs the "DHT sensor library" by Adafruit (and Adafruit Unified Sensor).

  DHT11 data pin -> D2, with a 10k pull-up resistor to 5V.
*/

#include <DHT.h>

#define DHTPIN 2        // digital pin the sensor is connected to
#define DHTTYPE DHT11   // the sensor model we are using

DHT dht(DHTPIN, DHTTYPE);

void setup() {
  Serial.begin(9600);
  Serial.println("DHT11 test!");

  dht.begin();
}

void loop() {
  // the DHT11 is slow, don't read it more often than every 2 seconds
  delay(2000);

  float humidity = dht.readHumidity();
  float temperature = dht.readTemperature();          // Celsius by default
  float fahrenheit = dht.readTemperature(true);       // pass true for Fahrenheit

  // if any reading failed, skip this round and try again
  if (isnan(humidity) || isnan(temperature)) {
    Serial.println("Failed to read from DHT sensor!");
    return;
  }

  Serial.print("Humidity: ");
  Serial.print(humidity);
  Serial.print(" %  Temperature: ");
  Serial.print(temperature);
  Serial.print(" C / ");
  Serial.print(fahrenheit);
  Serial.println(" F");
}

