/*
  DHT22 min / max tracker

  Reads the sensor every two seconds and remembers the lowest and
  highest temperature seen since the board was powered up.
*/

#include <DHT.h>

const int DHT_PIN = 4;

DHT dht(DHT_PIN, DHT22);

float minTemp = 1000.0;    // start with impossible values so the
float maxTemp = -1000.0;   // first reading always replaces them

void setup() {
  Serial.begin(9600);
  dht.begin();

  Serial.println("Temp(C)\tHumidity(%)\tMin\tMax");
}

void loop() {
  float temperature = dht.readTemperature();
  float humidity = dht.readHumidity();

  if (isnan(temperature) || isnan(humidity)) {
    Serial.println("Sensor read failed, retrying...");
    delay(2000);
    return;
  }

  if (temperature < minTemp) {
    minTemp = temperature;
  }
  if (temperature > maxTemp) {
    maxTemp = temperature;
  }

  Serial.print(temperature, 1);
  Serial.print("\t");
  Serial.print(humidity, 1);
  Serial.print("\t\t");
  Serial.print(minTemp, 1);
  Serial.print("\t");
  Serial.println(maxTemp, 1);

  delay(2000);
}

