/*
  LiquidCrystal "Hello World"

  Classic 16x2 character LCD wired in 4-bit mode.

  LCD RS -> pin 12
  LCD E  -> pin 11
  LCD D4 -> pin 5
  LCD D5 -> pin 4
  LCD D6 -> pin 3
  LCD D7 -> pin 2
  A 10k potentiometer sets the contrast on the V0 pin.
*/

#include <LiquidCrystal.h>

