LiquidCrystal lcd(12, 11, 5, 4, 3, 2);

void setup() {
  // tell the library how many columns and rows the display has
  lcd.begin(16, 2);

  // print a message on the first line
  lcd.print("Hello, World!");
}

void loop() {
  // move the cursor to column 0, line 1 (the second row)
  lcd.setCursor(0, 1);

  // print the number of seconds since reset
  lcd.print(millis() / 1000);
  lcd.print(" s");
}

