/*
  Potentiometer meter on an I2C LCD

  Shows the raw analog reading on the top line and a simple
  bar graph made of '#' characters on the bottom line.
*/

#include <Wire.h>
#include <LiquidCrystal_I2C.h>

LiquidCrystal_I2C lcd(0x27, 16, 2);

const int POT_PIN = A0;

void setup() {
  lcd.init();
  lcd.backlight();
  lcd.print("Pot meter");
  delay(1000);
  lcd.clear();
}

void loop() {
  int raw = analogRead(POT_PIN);
  int percent = map(raw, 0, 1023, 0, 100);
  int bars = map(raw, 0, 1023, 0, 16);   // how many blocks to draw

  lcd.setCursor(0, 0);
  lcd.print("Value:");
  lcd.print(raw);
  lcd.print("  ");        // spaces clear leftovers from longer numbers
  lcd.setCursor(12, 0);
  lcd.print(percent);
  lcd.print("% ");

  lcd.setCursor(0, 1);
  for (int i = 0; i < 16; i++) {
    if (i < bars) {
      lcd.print("#");
    } else {
      lcd.print(" ");
    }
  }

  delay(150);
}

