/*
  How many times has this Arduino been switched on?

  The EEPROM keeps its contents when the board loses power,
  so we can store a counter there and read it back on the next boot.
*/

#include <EEPROM.h>

#define COUNTER_ADDRESS 0

int bootCount = 0;

void setup() {
  Serial.begin(9600);
  delay(500);   // give the Serial Monitor a moment to open

  // read the value stored last time (a fresh chip reads back 255)
  bootCount = EEPROM.read(COUNTER_ADDRESS);

  if (bootCount > 250) {
    bootCount = 0;   // treat an unwritten cell as "never counted"
  }

  bootCount = bootCount + 1;

  // store the new value for the next power-up
  EEPROM.write(COUNTER_ADDRESS, bootCount);

  Serial.print("This board has started up ");
  Serial.print(bootCount);
  Serial.println(" time(s).");
}

void loop() {
  // nothing to do here
}

lib_11.code:
/*
  Brightness setting saved in EEPROM

  Every press of the button steps the LED brightness up one notch.
  The chosen level is written to EEPROM, so after unplugging and
  plugging the board back in the LED comes back at the same brightness.
*/

#include <EEPROM.h>

const int buttonPin = 2;            // button to GND, uses the internal pull-up
const int ledPin = 9;               // LED on a PWM pin
const int brightnessAddress = 10;   // where in EEPROM we keep the setting

int brightness = 0;
int lastButtonState = HIGH;

void setup() {
  pinMode(buttonPin, INPUT_PULLUP);
  pinMode(ledPin, OUTPUT);

  Serial.begin(9600);

  // restore the saved brightness
  brightness = EEPROM.read(brightnessAddress);
  analogWrite(ledPin, brightness);

  Serial.print("Restored brightness: ");
  Serial.println(brightness);
}

void loop() {
  int buttonState = digitalRead(buttonPin);

  // detect the moment the button goes from released to pressed
  if (buttonState == LOW && lastButtonState == HIGH) {
    brightness = brightness + 51;    // five steps from 0 to 255
    if (brightness > 255) {
      brightness = 0;
    }

    analogWrite(ledPin, brightness);

    // update() only writes if the value actually changed,
    // which saves EEPROM write cycles
    EEPROM.update(brightnessAddress, brightness);

    Serial.print("New brightness saved: ");
    Serial.println(brightness);

    delay(200);   // simple debounce
  }

  lastButtonState = buttonState;
}

lib_12.code:
/*
  Record temperature keeper

  Reads a DHT22, shows the current temperature on an I2C LCD and
  keeps the all-time highest reading in EEPROM so it is still there
  after a reset. Hold the button at start-up to clear the record.
*/

#include <Wire.h>
#include <LiquidCrystal_I2C.h>
#include <DHT.h>
#include <EEPROM.h>

#define DHTPIN   3
#define DHTTYPE  DHT22
#define RESET_BUTTON 4
#define RECORD_ADDRESS 0

DHT dht(DHTPIN, DHTTYPE);
LiquidCrystal_I2C lcd(0x27, 16, 2);

float recordTemp = 0.0;

void setup() {
  Serial.begin(9600);
  pinMode(RESET_BUTTON, INPUT_PULLUP);

  dht.begin();
  lcd.init();
  lcd.backlight();

  // a float takes four bytes, so we use put/get instead of read/write
  EEPROM.get(RECORD_ADDRESS, recordTemp);

  // a blank EEPROM gives nonsense, so sanity check the value
  if (isnan(recordTemp) || recordTemp < -40.0 || recordTemp > 100.0) {
    recordTemp = -40.0;
    EEPROM.put(RECORD_ADDRESS, recordTemp);
  }

  if (digitalRead(RESET_BUTTON) == LOW) {
    recordTemp = -40.0;
    EEPROM.put(RECORD_ADDRESS, recordTemp);
    lcd.print("Record cleared");
    delay(1500);
    lcd.clear();
  }
}

void loop() {
  float temperature = dht.readTemperature();

  if (isnan(temperature)) {
    Serial.println("DHT read failed");
    delay(2000);
    return;
  }

  if (temperature > recordTemp) {
    recordTemp = temperature;
    EEPROM.put(RECORD_ADDRESS, recordTemp);
    Serial.println("New record saved!");
  }

  lcd.setCursor(0, 0);
  lcd.print("Now:    ");
  lcd.print(temperature, 1);
  lcd.print(" C ");

  lcd.setCursor(0, 1);
  lcd.print("Record: ");
  lcd.print(recordTemp, 1);
  lcd.print(" C ");

  delay(2000);
}

