/*
  ESP32 weather web server

  Connects to WiFi and serves a simple page with the current
  temperature and humidity. Open the IP address printed in the
  Serial Monitor in any browser on the same network.
*/

#include <WiFi.h>
#include <WebServer.h>
#include <DHT.h>

#define DHTPIN 4
#define DHTTYPE DHT22

const char* ssid     = "YOUR_WIFI_NAME";
const char* password = "YOUR_WIFI_PASSWORD";

WebServer server(80);
DHT dht(DHTPIN, DHTTYPE);

void handleRoot() {
  float temperature = dht.readTemperature();
  float humidity = dht.readHumidity();

  String page = "<!DOCTYPE html><html><head>";
  page += "<meta http-equiv='refresh' content='5'>";
  page += "<meta name='viewport' content='width=device-width, initial-scale=1'>";
  page += "<title>ESP32 Weather</title></head><body>";
  page += "<h1>ESP32 Weather Station</h1>";

  if (isnan(temperature) || isnan(humidity)) {
    page += "<p>Sensor read failed.</p>";
  } else {
    page += "<p>Temperature: " + String(temperature, 1) + " &deg;C</p>";
    page += "<p>Humidity: " + String(humidity, 1) + " %</p>";
  }

  page += "<p>Uptime: " + String(millis() / 1000) + " s</p>";
  page += "</body></html>";

  server.send(200, "text/html", page);
}

void handleNotFound() {
  server.send(404, "text/plain", "Page not found");
}

void setup() {
  Serial.begin(115200);
  dht.begin();

  WiFi.begin(ssid, password);
  Serial.print("Connecting to WiFi");
  while (WiFi.status() != WL_CONNECTED) {
    delay(500);
    Serial.print(".");
  }
  Serial.println();
  Serial.print("Open this address in your browser: http://");
  Serial.println(WiFi.localIP());

  server.on("/", handleRoot);
  server.onNotFound(handleNotFound);
  server.begin();
  Serial.println("HTTP server started");
}

void loop() {
  server.handleClient();
}

