/*
  Send sensor data to a server

  Every 30 seconds the ESP32 reads the DHT22 and sends the values
  to a web endpoint as JSON. Replace serverUrl with your own address.
*/

#include <WiFi.h>
#include <HTTPClient.h>
#include <DHT.h>

#define DHT_PIN  15
#define DHT_TYPE DHT22

const char* WIFI_SSID     = "YOUR_WIFI_NAME";
const char* WIFI_PASSWORD = "YOUR_WIFI_PASSWORD";
const char* serverUrl     = "http://192.168.1.50:8000/api/readings";

const unsigned long sendInterval = 30000;   // 30 seconds
unsigned long lastSend = 0;

DHT dht(DHT_PIN, DHT_TYPE);

void connectToWiFi() {
  WiFi.begin(WIFI_SSID, WIFI_PASSWORD);
  Serial.print("Connecting to WiFi");
  while (WiFi.status() != WL_CONNECTED) {
    delay(500);
    Serial.print(".");
  }
  Serial.println();
  Serial.print("Connected, IP: ");
  Serial.println(WiFi.localIP());
}

void setup() {
  Serial.begin(115200);
  dht.begin();
  connectToWiFi();
}

void loop() {
  if (millis() - lastSend < sendInterval) {
    return;
  }
  lastSend = millis();

  float temperature = dht.readTemperature();
  float humidity = dht.readHumidity();

  if (isnan(temperature) || isnan(humidity)) {
    Serial.println("Sensor read failed, skipping this upload");
    return;
  }

  if (WiFi.status() != WL_CONNECTED) {
    Serial.println("WiFi down, reconnecting");
    connectToWiFi();
  }

  HTTPClient http;
  http.begin(serverUrl);
  http.addHeader("Content-Type", "application/json");

  String payload = "{\"temperature\":" + String(temperature, 1) +
                   ",\"humidity\":" + String(humidity, 1) + "}";

  int responseCode = http.POST(payload);

  if (responseCode > 0) {
    Serial.print("Server replied with code ");
    Serial.println(responseCode);
    Serial.println(http.getString());
  } else {
    Serial.print("POST failed, error: ");
    Serial.println(http.errorToString(responseCode));
  }

  http.end();
}

lib_16.code:
/*
  ESP32 LED fade with ledc

  The ESP32 has no analogWrite(), it uses the LEDC hardware PWM
  peripheral instead. This sketch fades an LED up and down.

  (Written for ESP32 Arduino core 3.x, where ledcAttach() takes
  the pin, the frequency and the resolution.)
*/

#define LED_PIN        5
#define PWM_FREQ       5000    // 5 kHz
#define PWM_RESOLUTION 8       // 8 bit -> duty values 0..255

int dutyCycle = 0;

void setup() {
  Serial.begin(115200);

  // set up PWM on the LED pin
  ledcAttach(LED_PIN, PWM_FREQ, PWM_RESOLUTION);
}

void loop() {
  // fade in
  for (dutyCycle = 0; dutyCycle <= 255; dutyCycle++) {
    ledcWrite(LED_PIN, dutyCycle);
    delay(10);
  }

  // fade out
  for (dutyCycle = 255; dutyCycle >= 0; dutyCycle--) {
    ledcWrite(LED_PIN, dutyCycle);
    delay(10);
  }
}

lib_17.code:
/*
  ESP32 dimmer

  A potentiometer on GPIO 34 sets the brightness of an LED on GPIO 16
  through one of the ESP32's LEDC PWM channels.

  Note: the ESP32 ADC is 12 bit, so analogRead() returns 0..4095.
*/

const int potPin = 34;      // ADC pin, input only
const int ledPin = 16;

const int ledChannel = 0;
const int freq = 5000;
const int resolution = 8;

void setup() {
  Serial.begin(115200);

  // configure the PWM channel and hook the LED pin to it
  ledcSetup(ledChannel, freq, resolution);
  ledcAttachPin(ledPin, ledChannel);
}

void loop() {
  int potValue = analogRead(potPin);

  // 12 bit reading down to an 8 bit duty cycle
  int dutyCycle = map(potValue, 0, 4095, 0, 255);

  ledcWrite(ledChannel, dutyCycle);

  Serial.print("pot: ");
  Serial.print(potValue);
  Serial.print("  duty: ");
  Serial.println(dutyCycle);

  delay(50);
}

lib_18.code:
/*
  ESP32 touch button

  The ESP32 can sense a touch on certain pins with touchRead().
  An untouched pin gives a fairly high number; touching it makes
  the value drop. Here a touch toggles the on-board LED.

  Touch pin T0 is GPIO 4. Just solder a wire or a piece of foil to it.
*/

#define TOUCH_PIN T0
#define LED_PIN   2

const int touchThreshold = 40;   // tune this after watching the values

bool ledIsOn = false;
bool wasTouched = false;

void setup() {
  Serial.begin(115200);
  pinMode(LED_PIN, OUTPUT);
  digitalWrite(LED_PIN, LOW);
}

void loop() {
  int touchValue = touchRead(TOUCH_PIN);
  Serial.println(touchValue);

  bool isTouched = (touchValue < touchThreshold);

  // only react on the moment the finger lands, not the whole time
  if (isTouched && !wasTouched) {
    ledIsOn = !ledIsOn;
    digitalWrite(LED_PIN, ledIsOn ? HIGH : LOW);

    Serial.print("LED is now ");
    Serial.println(ledIsOn ? "ON" : "OFF");

    delay(300);   // rough debounce
  }

  wasTouched = isTouched;
  delay(50);
}

