/*
  Touch controlled servo (ESP32)

  Two touch pads act as left / right buttons for a servo.
  The regular Servo library does not work on the ESP32,
  so install "ESP32Servo" from the Library Manager.
*/

#include <ESP32Servo.h>

#define SERVO_PIN   18
#define TOUCH_LEFT  T0    // GPIO 4
#define TOUCH_RIGHT T3    // GPIO 15

const int TOUCH_THRESHOLD = 35;
const int STEP = 5;

Servo myServo;
int angle = 90;

void setup() {
  Serial.begin(115200);

  myServo.setPeriodHertz(50);            // standard 50 Hz servo
  myServo.attach(SERVO_PIN, 500, 2400);  // min and max pulse width in us
  myServo.write(angle);

  Serial.println("Touch the left or right pad to move the servo.");
}

void loop() {
  int leftValue = touchRead(TOUCH_LEFT);
  int rightValue = touchRead(TOUCH_RIGHT);

  if (leftValue < TOUCH_THRESHOLD) {
    angle = angle - STEP;
    if (angle < 0) {
      angle = 0;
    }
    myServo.write(angle);
    Serial.print("angle: ");
    Serial.println(angle);
    delay(150);
  }

  if (rightValue < TOUCH_THRESHOLD) {
    angle = angle + STEP;
    if (angle > 180) {
      angle = 180;
    }
    myServo.write(angle);
    Serial.print("angle: ");
    Serial.println(angle);
    delay(150);
  }

  delay(50);
}

